// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/shipments", wrapper.ListShipments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/shipments", wrapper.CreateShipment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/shipments/{ref}", wrapper.GetShipment)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/shipments/{ref}", wrapper.UpdateShipment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/shipments/{ref}/assign", wrapper.AssignShipment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/shipments/{ref}/cancel", wrapper.CancelShipment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/shipments/{ref}/events", wrapper.ShipmentEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/drivers", wrapper.ListDrivers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/openapi.json", wrapper.GetPublicSpecification)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/driver/config", wrapper.GetDriverConfig)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/login", wrapper.DriverSignIn)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/pin-reset/request", wrapper.RequestDriverPINReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/pin-reset/confirm", wrapper.ConfirmDriverPINReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/logout", wrapper.DriverSignOut)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/pin", wrapper.ChangeDriverPIN)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/driver/sync", wrapper.DriverSync)

	return m
}

// WebhookReceiverInterface represents handlers for receiving inbound
// webhook requests. Each webhook becomes a Handle*Webhook
// method that the implementation fills in. The caller mounts the per-
// webhook http.Handler returned by {Op}WebhookHandler at
// whatever URL path they advertise to senders.
type WebhookReceiverInterface interface {
	// A shipment is booked, from the dashboard, a CSV file or the API
	// HandleShipmentCreatedWebhook handles the POST webhook for shipment.created.
	HandleShipmentCreatedWebhook(w http.ResponseWriter, r *http.Request)
	// A shipment is delivered; sent as well as its status change
	// HandleShipmentDeliveredWebhook handles the POST webhook for shipment.delivered.
	HandleShipmentDeliveredWebhook(w http.ResponseWriter, r *http.Request)
	// The driver reports a problem (as well as the status change), or the receiver does on the confirmation page (event type customer_issue)
	// HandleShipmentIssueReportedWebhook handles the POST webhook for shipment.issue_reported.
	HandleShipmentIssueReportedWebhook(w http.ResponseWriter, r *http.Request)
	// A shipment's status changes; data.event has from_status and to_status
	// HandleShipmentStatusChangedWebhook handles the POST webhook for shipment.status_changed.
	HandleShipmentStatusChangedWebhook(w http.ResponseWriter, r *http.Request)
}

// WebhookReceiverMiddlewareFunc wraps an http.Handler with cross-
// cutting behavior (signature verification, logging, rate limiting, ...).
type WebhookReceiverMiddlewareFunc func(http.Handler) http.Handler

// ShipmentCreatedWebhookHandler returns the http.Handler for the shipment.created webhook.
// Mount this at the URL path advertised to webhook senders. errHandler
// may be nil; if so, parameter-binding errors return 400 with the error
// message. Middlewares are applied in the order provided -- the last
// argument becomes the outermost wrapper.
func ShipmentCreatedWebhookHandler(si WebhookReceiverInterface, errHandler func(w http.ResponseWriter, r *http.Request, err error), middlewares ...WebhookReceiverMiddlewareFunc) http.Handler {
	if errHandler == nil {
		errHandler = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	var h http.Handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		si.HandleShipmentCreatedWebhook(w, r)
	})
	for _, mw := range middlewares {
		h = mw(h)
	}
	return h
}

